cpp.setup:
auto* control = new fluent::basicinput::TreeSelect(%PARENT%);
auto* model = new QStandardItemModel(control);
for (const auto& text : {QStringLiteral("Design"), QStringLiteral("Engineering"), QStringLiteral("Research")}) {
    auto* item = new QStandardItem(text);
    item->setData(text, Qt::UserRole);
    model->appendRow(item);
}
control->setModel(model);
